
const KEY='sunday-table-v1';const seedRecipes=[{id:'r1',name:'Crispy chickpeas & greens',source:'NYT Cooking',ingredients:['1 can chickpeas','1 bunch kale','1 lemon','2 tbsp olive oil','3 cloves garlic'],notes:'Finish with lots of lemon.',emoji:'🥬',time:'30 min'},{id:'r2',name:'Creamy lemon orzo',source:'Saved from Instagram',ingredients:['1 cup orzo','2 lemons','3 cups vegetable broth','½ cup parmesan','2 tbsp butter'],notes:'One pot, weeknight favorite.',emoji:'🍋',time:'25 min'},{id:'r3',name:'Sheet-pan salmon',source:'Bon Appétit',ingredients:['4 salmon fillets','1 lb baby potatoes','1 bunch asparagus','1 tbsp Dijon mustard','1 lemon'],notes:'Add asparagus halfway through.',emoji:'🐟',time:'40 min'},{id:'r4',name:'Cozy tomato butter beans',source:'TikTok',ingredients:['2 cans butter beans','1 can crushed tomatoes','½ cup cream','4 cloves garlic','Fresh basil'],notes:'Great with crusty bread.',emoji:'🍅',time:'35 min'}];let state=JSON.parse(localStorage.getItem(KEY)||'null')||{recipes:seedRecipes,plans:{},items:[],weekOffset:0};state.events??=[];state.dayEvents??=[];let weekOffset=state.weekOffset||0;let selectedEventId=null;let guestMode=false;const save=()=>{state.weekOffset=weekOffset;state.localSavedAt=Date.now();localStorage.setItem(KEY,JSON.stringify(state));window.DinnerTableFirebase?.afterSave?.();render()};const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const monday=(off=0)=>{let d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7)+off*7);return d};const keyDate=d=>d.toISOString().slice(0,10);const weekDates=()=>Array.from({length:7},(_,i)=>{let d=monday(weekOffset);d.setDate(d.getDate()+i);return d});const partyThemeMap={classic:{key:'classic',label:'Classic',emoji:'🍽️'},summer:{key:'summer',label:'Summer',emoji:'☀️'},spring:{key:'spring',label:'Spring',emoji:'🌷'},halloween:{key:'halloween',label:'Halloween',emoji:'🎃'},thanksgiving:{key:'thanksgiving',label:'Thanksgiving',emoji:'🍂'},christmas:{key:'christmas',label:'Christmas',emoji:'🎄'}};function partyTheme(event){return partyThemeMap[event?.theme]||partyThemeMap.classic}
function render(){document.getElementById('weekLabel').textContent=`${weekDates()[0].toLocaleDateString('en-US',{month:'short',day:'numeric'})} – ${weekDates()[6].toLocaleDateString('en-US',{month:'short',day:'numeric'})}`;document.getElementById('recipeCount').textContent=state.recipes.length;document.getElementById('shopCount').textContent=state.items.filter(x=>!x.checked).length;renderWeek();renderRecipes();renderShopping();renderEvents()}
function renderWeek(){let now=keyDate(new Date()),grid=document.getElementById('weekGrid'),count=0;grid.innerHTML=weekDates().map(d=>{let k=keyDate(d), meals=(state.plans[k]||[]);count+=meals.length;return `<article class="day ${k===now?'today':''}"><div class="day-head"><span class="day-name">${d.toLocaleDateString('en-US',{weekday:'short'})}</span><span class="day-date">${d.toLocaleDateString('en-US',{month:'numeric',day:'numeric'})}</span></div>${['Breakfast','Lunch','Dinner'].map(type=>{let entries=meals.filter(m=>m.meal===type);return `<div class="meal-slot"><div class="slot-label">${type}</div>${entries.map(m=>{let r=state.recipes.find(x=>x.id===m.recipe);return r?`<div class="meal-card">${esc(r.name)}<button class="remove" title="Remove" data-remove="${k}|${m.id}">×</button></div>`:''}).join('')}<button class="add-meal" data-add="${k}|${type}">＋ Add</button></div>`}).join('')}</article>`}).join('');document.getElementById('planSummary').textContent=count?`${count} meal${count===1?'':'s'} on the calendar`:"A few ideas go a long way. Add a recipe to get started.";grid.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>openPlan(...b.dataset.add.split('|')));grid.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{let [k,id]=b.dataset.remove.split('|');state.plans[k]=state.plans[k].filter(x=>x.id!==id);save()})}
function renderRecipes(){let q=document.getElementById('search').value.toLowerCase(),g=document.getElementById('recipeGrid');let recipes=state.recipes.filter(r=>r.name.toLowerCase().includes(q)||r.source.toLowerCase().includes(q));g.innerHTML=recipes.map(r=>`<article class="card recipe"><div class="recipe-image"><span>${r.emoji||'🍽️'}</span><div class="source-chip">${esc(r.source||'My recipe')}</div></div><div class="recipe-body"><h3>${esc(r.name)}</h3><div class="recipe-meta"><span>◷ ${r.time||'Recipe'}</span><span>▤ ${r.ingredients.length} ingredients</span></div>${r.notes?`<p style="color:var(--muted);font-size:11px;margin:10px 0 0">${esc(r.notes)}</p>`:''}<div class="recipe-actions"><button class="btn small" data-share-recipe="${r.id}">Share</button><button class="btn small" data-plan-recipe="${r.id}">＋ Plan it</button><button class="btn small" data-delete-recipe="${r.id}">Remove</button></div></div></article>`).join('')+`<button class="add-tile" id="addTile"><span><b>＋ Save a recipe</b>From a link, a post, or your own notes</span></button>`;g.querySelector('#addTile').onclick=()=>document.getElementById('recipeDialog').showModal();g.querySelectorAll('[data-plan-recipe]').forEach(b=>b.onclick=()=>openPlan(keyDate(monday(weekOffset)), 'Dinner',b.dataset.planRecipe));g.querySelectorAll('[data-delete-recipe]').forEach(b=>b.onclick=()=>{state.recipes=state.recipes.filter(r=>r.id!==b.dataset.deleteRecipe);save()})}
function renderShopping(){let wrap=document.getElementById('shoppingItems'),items=state.items;if(!items.length){wrap.innerHTML='<div class="empty"><b>Your list is ready to fill.</b>Plan a few recipes, then build your list from the ingredients.</div>';return}let cats={Produce:[],Pantry:[],Dairy:[],Other:[]};items.forEach((item,i)=>{let n=item.name.toLowerCase(),c=/lemon|kale|asparagus|basil|parsley|potato|greens|garlic/.test(n)?'Produce':/milk|cream|butter|parmesan|cheese|yogurt/.test(n)?'Dairy':/can|beans|chickpea|orzo|oil|tomato|broth|mustard/.test(n)?'Pantry':'Other';cats[c].push({...item,i})});wrap.innerHTML=Object.entries(cats).filter(([,a])=>a.length).map(([c,a])=>`<div class="category">${c}</div>${a.map(x=>`<label class="shop-item ${x.checked?'checked':''}"><input type="checkbox" data-check="${x.i}" ${x.checked?'checked':''}><span>${esc(x.name)}</span><span class="qty">${esc(x.qty||'')}</span><button class="remove" data-del-item="${x.i}" style="position:static;margin-left:7px">×</button></label>`).join('')}`).join('');wrap.querySelectorAll('[data-check]').forEach(b=>b.onchange=()=>{state.items[b.dataset.check].checked=b.checked;save()});wrap.querySelectorAll('[data-del-item]').forEach(b=>b.onclick=()=>{state.items.splice(+b.dataset.delItem,1);save()})}
function openPlan(day,meal,recipe){let sel=document.querySelector('#planForm select[name=recipe]');sel.innerHTML=state.recipes.map(r=>`<option value="${r.id}" ${r.id===recipe?'selected':''}>${esc(r.name)}</option>`).join('');if(!state.recipes.length){toast('Save a recipe first');return}document.querySelector('#planForm [name=day]').value=day;document.querySelector('#planForm select[name=meal]').value=meal;document.getElementById('planDialog').showModal()}
let toastTimer;function toast(s,duration=2200){let t=document.getElementById('toast');t.textContent=s;t.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',duration)}document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab,.view').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById(b.dataset.view).classList.add('active')});document.getElementById('newRecipe').onclick=()=>document.getElementById('recipeDialog').showModal();document.getElementById('search').oninput=renderRecipes;document.getElementById('prevWeek').onclick=()=>{weekOffset--;save()};document.getElementById('nextWeek').onclick=()=>{weekOffset++;save()};document.getElementById('thisWeek').onclick=()=>{weekOffset=0;save()};document.getElementById('clearWeek').onclick=()=>{weekDates().forEach(d=>delete state.plans[keyDate(d)]);save()};document.getElementById('recipeForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);if(!f.get('name'))return;state.recipes.unshift({id:crypto.randomUUID(),name:f.get('name').trim(),source:f.get('source').trim()||'My recipe',ingredients:f.get('ingredients').split('\n').map(x=>x.trim()).filter(Boolean),notes:f.get('notes').trim(),emoji:'🍽️'});e.target.reset();document.getElementById('recipeDialog').close();save();toast('Recipe saved to your box')};document.getElementById('planForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),day=f.get('day');state.plans[day]??=[];state.plans[day].push({id:crypto.randomUUID(),recipe:f.get('recipe'),meal:f.get('meal')});document.getElementById('planDialog').close();save();toast('Added to your week')};document.getElementById('buildList').onclick=()=>{let ids=new Set(weekDates().flatMap(d=>(state.plans[keyDate(d)]||[]).map(m=>m.recipe))),existing=new Set(state.items.map(i=>i.name.toLowerCase()));let added=0;state.recipes.filter(r=>ids.has(r.id)).forEach(r=>r.ingredients.forEach(name=>{if(!existing.has(name.toLowerCase())){state.items.push({name,qty:'',checked:false});existing.add(name.toLowerCase());added++}}));save();toast(added?`${added} ingredients added`:'Your list is up to date')};document.getElementById('addItem').onclick=()=>document.getElementById('itemDialog').showModal();document.getElementById('itemForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);state.items.push({name:f.get('name').trim(),qty:f.get('qty').trim(),checked:false});e.target.reset();document.getElementById('itemDialog').close();save()};


function renderEvents(){const grid=document.getElementById('eventGrid'),list=document.getElementById('partyList'),detail=document.getElementById('eventDetail');if(!grid||!detail)return;document.getElementById('eventCount').textContent=state.events.length;const event=state.events.find(e=>e.id===selectedEventId);list.hidden=!!event;detail.hidden=!event;if(!event){grid.innerHTML=state.events.length?state.events.map(e=>`<article class="card event-card theme-${partyTheme(e).key}"><div class="event-theme-art" aria-hidden="true">${partyTheme(e).emoji}</div><div><div class="event-date">${e.date?new Date(`${e.date}T12:00:00`).toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'}):'Date to be decided'}</div><h3>${esc(e.name)}</h3><p>${e.contributions.length} item${e.contributions.length===1?'':'s'} on the menu</p></div><div class="event-actions"><button class="btn small" data-open-event="${e.id}">Open menu →</button></div></article>`).join(''):'<div class="card empty-events"><b style="display:block;font:600 20px Playfair Display,serif;color:var(--ink);margin-bottom:8px">Your next gathering starts here.</b>Create an event to invite people into the menu.</div>';grid.querySelectorAll('[data-open-event]').forEach(b=>b.onclick=()=>{selectedEventId=b.dataset.openEvent;guestMode=Boolean(state.events.find(item=>item.id===selectedEventId)?.ownerUid&&state.events.find(item=>item.id===selectedEventId)?.ownerUid!==window.DinnerTableFirebase?.uid);renderEvents()});return}
const categoryIcons={Main:'🍲',Side:'🥗',Snack:'🥨',Drink:'🥂',Dessert:'🍰',Other:'🍽️'},categories=['Main','Side','Snack','Drink','Dessert','Other'];const groups=categories.map(c=>{const items=event.contributions.filter(x=>x.category===c);if(!items.length)return '';return `<div class="menu-group"><h3>${categoryIcons[c]} ${c}s</h3>${items.map(x=>`<div class="contribution"><div class="contribution-icon">${categoryIcons[c]}</div><div class="contribution-main"><b>${esc(x.item)}</b><span>Bringing ${esc(x.person)}${x.note?` · ${esc(x.note)}`:''}</span></div>${!guestMode?`<button class="remove" data-remove-contribution="${x.id}" title="Remove contribution">×</button>`:''}</div>`).join('')}</div>`}).join('');const n=event.contributions.length;detail.innerHTML=`<div class="party-toolbar"><button class="btn small" id="backEvents">← All events</button><label class="guest-toggle"><input type="checkbox" id="guestPreview" ${guestMode?'checked':''}> Preview as guest</label></div><div class="party-event-banner theme-${partyTheme(event).key}"><span class="party-theme-mark" aria-hidden="true">${partyTheme(event).emoji}</span><div><div class="eyebrow">${guestMode?'You’re invited':'You’re hosting'}</div><h2 class="party-title">${esc(event.name)}</h2></div></div><p style="color:var(--muted);margin:0">${event.date?new Date(`${event.date}T12:00:00`).toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'}):'Date to be decided'}${event.note?` · ${esc(event.note)}`:''}</p><div class="local-note"><b>Local preview:</b> this menu is saved in this browser only. Firebase will make the invite link and guest contributions work across devices.</div><div class="party-columns"><div class="card menu-card">${groups||'<div class="empty"><b>No contributions yet.</b>Be the first to add something to the menu.</div>'}${!guestMode?`<div class="host-menu-add"><button class="btn primary" id="hostAddContribution">＋ Add food to the menu</button></div>`:guestMode&&event.accepting?`<div class="guest-add"><button class="btn primary" id="addContribution">＋ Add what you’re bringing</button></div>`:''}${guestMode&&!event.accepting?'<p style="color:var(--muted);font-size:12px">The host has closed contributions for this menu.</p>':''}</div><aside class="card host-panel">${guestMode?`<h3>Guest preview</h3><p>This is how a guest will see the menu. Try adding a dish; it will appear here in this local preview.</p>${event.accepting?'<button class="btn primary" id="guestAddSide">＋ Add a contribution</button>':''}`:`<h3>Host controls</h3><p>${n} contribution${n===1?'':'s'} so far. ${event.accepting?'Guests can add to this menu.':'Guest contributions are closed.'}</p><div class="host-actions"><button class="btn" id="toggleAccept">${event.accepting?'Close':'Reopen'} contributions</button><button class="btn" id="deleteEvent">Delete event</button></div><p style="margin:14px 0 0">You can remove any contribution from the menu. Guest permissions and real invite links will be connected with Firebase.</p>`}</aside></div>`;
detail.querySelector('#backEvents').onclick=()=>{selectedEventId=null;guestMode=false;renderEvents()};detail.querySelector('#guestPreview').onchange=e=>{guestMode=e.target.checked;renderEvents()};detail.querySelectorAll('[data-remove-contribution]').forEach(b=>b.onclick=()=>{event.contributions=event.contributions.filter(x=>x.id!==b.dataset.removeContribution);save()});detail.querySelector('#addContribution')?.addEventListener('click',()=>openContribution(event.id));detail.querySelector('#hostAddContribution')?.addEventListener('click',()=>openContribution(event.id));detail.querySelector('#guestAddSide')?.addEventListener('click',()=>openContribution(event.id));detail.querySelector('#toggleAccept')?.addEventListener('click',()=>{event.accepting=!event.accepting;save()});detail.querySelector('#inviteLater')?.addEventListener('click',()=>toast('Firebase will enable shareable guest links'));detail.querySelector('#deleteEvent')?.addEventListener('click',()=>{if(confirm('Delete this event and its menu?')){state.events=state.events.filter(x=>x.id!==event.id);selectedEventId=null;save()}})}
function openContribution(eventId){const form=document.getElementById('contributionForm'),field=form.elements.event||(()=>{const input=document.createElement('input');input.type='hidden';input.name='event';form.prepend(input);return input})();field.value=eventId;form.elements.person.value=window.DinnerTableFirebase?.displayName||state.profile?.name||'';document.querySelector('#contributionDialog h2').textContent=guestMode?'Add what you’re bringing':'Add food to the menu';document.getElementById('contributionDialog').showModal()}
document.getElementById('newEvent').onclick=()=>document.getElementById('eventDialog').showModal();document.getElementById('eventForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const event={id:crypto.randomUUID(),name:f.get('name').trim(),date:f.get('date'),note:f.get('note').trim(),accepting:true,contributions:[]};state.events.unshift(event);selectedEventId=event.id;guestMode=false;e.target.reset();document.getElementById('eventDialog').close();save();toast('Your party menu is ready')};document.getElementById('contributionForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),event=state.events.find(x=>x.id===f.get('event'));if(!event||(!event.accepting&&guestMode)){document.getElementById('contributionDialog').close();toast('This menu is closed');return}event.contributions.push({id:crypto.randomUUID(),person:f.get('person').trim(),item:f.get('item').trim(),category:f.get('category'),note:f.get('note').trim()});e.target.reset();document.getElementById('contributionDialog').close();save();toast('Added to the menu')};
const localDayKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const weekdayNames=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
function openScheduleEvent(date,eventId=''){
  const form=document.getElementById('scheduleEventForm'),existing=state.dayEvents.find(item=>item.id===eventId);
  form.reset();form.elements.id.value=existing?.id||'';form.elements.date.value=existing?.date||date;
  form.elements.title.value=existing?.title||'';form.elements.details.value=existing?.details||'';
  document.getElementById('scheduleEventHeading').textContent=existing?'Edit your day plan':'Add a private day plan';
  const friends=window.DinnerTableFirebase?.friends||[],options=document.getElementById('scheduleFriendOptions');options.className='schedule-friend-options';
  options.innerHTML=friends.length?friends.map(friend=>`<label class="schedule-friend-option"><input type="checkbox" name="shareWith" value="${esc(friend.uid)}" ${(existing?.sharedWith||[]).includes(friend.uid)?'checked':''}><span>${esc(friend.displayName)}</span></label>`).join(''):'<p class="profile-note">Connect with a friend first if you want to share this plan. It stays private to you by default.</p>';
  document.getElementById('scheduleEventDialog').showModal();
}
function persistScheduleEvent(event){const persist=window.DinnerTableFirebase?.saveScheduledEvent;if(typeof persist!=='function')return;Promise.resolve(persist(event)).then(saved=>{if(saved)toast('Day plan saved and shared with your selected friends')}).catch(error=>{console.error('Could not save the day plan to Firebase.',error);toast(`Saved on this device, but Firebase could not save the day plan (${error?.code||'error'}): ${error?.message||'unknown error'}`,8000)})}
function removeScheduleEvent(id){const event=state.dayEvents.find(item=>item.id===id);if(!event)return;state.dayEvents=state.dayEvents.map(item=>item.id===id?{...item,deleted:true,sharedWith:[],updatedAt:Date.now()}:item);save();const remove=window.DinnerTableFirebase?.deleteScheduledEvent;if(typeof remove==='function')Promise.resolve(remove(id)).catch(error=>{console.error('Could not remove the shared day plan.',error);toast(`Removed here, but Firebase could not update it: ${error?.message||'unknown error'}`,8000)})}
function renderWeek(){
  const now=localDayKey(new Date()),grid=document.getElementById('weekGrid'),shared=window.DinnerTableFirebase?.sharedScheduleEvents||[];let count=0;
  grid.innerHTML=weekDates().map(d=>{
    const dayKey=keyDate(d),dateKey=localDayKey(d),meals=state.plans[dayKey]||[],party=state.events.find(e=>e.date===dateKey),ownEvents=(state.dayEvents||[]).filter(item=>item.date===dateKey&&!item.deleted),sharedEvents=shared.filter(item=>item.date===dateKey);
    if(!party)count+=meals.length;
    const scheduleMarkup=`<div class="day-schedule-list">${ownEvents.map(item=>`<div class="day-schedule-item"><div><b>${esc(item.title)}</b>${item.details?`<small>${esc(item.details)}</small>`:''}<small class="day-schedule-privacy">${item.sharedWith?.length?`Shared with ${item.sharedWith.length} friend${item.sharedWith.length===1?'':'s'}`:'Private to you'}</small></div><span class="day-schedule-actions"><button type="button" data-edit-schedule="${esc(item.id)}" aria-label="Edit ${esc(item.title)}">Edit</button><button type="button" data-delete-schedule="${esc(item.id)}" aria-label="Remove ${esc(item.title)}">×</button></span></div>`).join('')}${sharedEvents.map(item=>`<div class="day-schedule-item shared-day-schedule"><div><b>${esc(item.title)}</b>${item.details?`<small>${esc(item.details)}</small>`:''}<small>Shared by ${esc(item.ownerName||'A friend')}</small></div></div>`).join('')}</div>`;
    const dayContent=party?`<div class="party-day-card"><b>🎉 Party day</b>${esc(party.name)}<br><button data-open-party="${party.id}">Open shared menu →</button></div>${scheduleMarkup}<button class="day-schedule-add" type="button" data-add-schedule="${dateKey}">＋ Add a personal plan</button>`:`<button class="day-party" data-mark-party="${dateKey}">＋ Make this a party day</button>${scheduleMarkup}<button class="day-schedule-add" type="button" data-add-schedule="${dateKey}">＋ Add a personal plan</button>${['Breakfast','Lunch','Dinner'].map(type=>{const entries=meals.filter(m=>m.meal===type);return `<div class="meal-slot"><div class="slot-label">${type}</div>${entries.map(m=>{const r=state.recipes.find(x=>x.id===m.recipe);return r?`<div class="meal-card">${esc(r.name)}<button class="remove" title="Remove" data-remove="${dayKey}|${m.id}">×</button></div>`:''}).join('')}<button class="add-meal" data-add="${dayKey}|${type}">＋ Add</button></div>`}).join('')}`;
    return `<article class="day ${dateKey===now?'today':''}" data-date="${dateKey}" data-plan-key="${dayKey}"><div class="day-head"><span class="day-name">${d.toLocaleDateString('en-US',{weekday:'short'})}</span><span class="day-date">${d.toLocaleDateString('en-US',{month:'numeric',day:'numeric'})}</span></div>${dayContent}</article>`;
  }).join('');
  document.getElementById('planSummary').textContent=count?`${count} meal${count===1?'':'s'} on the calendar`:'Add meals, private day plans, or a shared dinner.';
  grid.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>openPlan(...b.dataset.add.split('|')));
  grid.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const [k,id]=b.dataset.remove.split('|');state.plans[k]=state.plans[k].filter(x=>x.id!==id);save()});
  grid.querySelectorAll('[data-mark-party]').forEach(b=>b.onclick=()=>{document.querySelector('#eventForm [name=date]').value=b.dataset.markParty;document.getElementById('eventDialog').showModal()});
  grid.querySelectorAll('[data-open-party]').forEach(b=>b.onclick=()=>{selectedEventId=b.dataset.openParty;const event=state.events.find(item=>item.id===selectedEventId);guestMode=Boolean(event?.ownerUid&&event.ownerUid!==window.DinnerTableFirebase?.uid);document.querySelector('.tab[data-view="parties"]').click();renderEvents()});
  grid.querySelectorAll('[data-add-schedule]').forEach(b=>b.onclick=()=>openScheduleEvent(b.dataset.addSchedule));
  grid.querySelectorAll('[data-edit-schedule]').forEach(b=>b.onclick=()=>openScheduleEvent('',b.dataset.editSchedule));
  grid.querySelectorAll('[data-delete-schedule]').forEach(b=>b.onclick=()=>removeScheduleEvent(b.dataset.deleteSchedule));
}
document.getElementById('scheduleEventForm').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target),event={id:data.get('id')||crypto.randomUUID(),date:data.get('date'),title:String(data.get('title')||'').trim(),details:String(data.get('details')||'').trim(),sharedWith:data.getAll('shareWith').map(String)};if(!event.title)return;const index=state.dayEvents.findIndex(item=>item.id===event.id);if(index>=0)state.dayEvents[index]=event;else state.dayEvents.push(event);document.getElementById('scheduleEventDialog').close();save();persistScheduleEvent(event);if(!window.DinnerTableFirebase?.signedIn)toast('Private day plan saved on this device')};
