let activeRecipeCategory='All categories';
function recipeCategory(recipe){if(recipe.category)return recipe.category;return ({r1:'Side',r2:'Entree',r3:'Entree',r4:'Entree'})[recipe.id]||'Other'}
function persistRecipeToCloud(recipe){const persist=window.DinnerTableFirebase?.saveRecipe;if(typeof persist!=='function')return;Promise.resolve(persist(recipe)).then(saved=>{if(saved)toast('Recipe saved to Firebase and your recipe box')}).catch(error=>{console.error('Recipe could not be saved to Firebase.',error);toast(`Recipe is saved on this device, but Firebase did not save it (${error?.code||'error'}): ${error?.message||'unknown error'}`,8000)})}
function recipeUrl(source){const raw=(source||'').trim();if(!raw)return '';try{const url=new URL(/^https?:\/\//i.test(raw)?raw:`https://${raw}`);return url.hostname.includes('.')?url.href:''}catch{return ''}}
function showRecipeDetails(id){const recipe=state.recipes.find(r=>r.id===id);if(!recipe)return;const link=recipeUrl(recipe.source),content=document.getElementById('recipeDetailsContent');content.innerHTML=`<span class="recipe-category">${esc(recipeCategory(recipe))}</span><h2>${esc(recipe.name)}</h2><p class="details-source">${link?`<a href="${esc(link)}" target="_blank" rel="noopener noreferrer">Open original recipe ↗</a>`:`Source: ${esc(recipe.source||'My recipe')} · No link saved`}</p><h3>Ingredients</h3>${recipe.ingredients?.length?`<ul class="ingredient-list">${recipe.ingredients.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:'<p class="no-ingredients">No ingredients saved yet.</p>'}${recipe.instructions?.length?`<h3>Directions</h3><ol class="ingredient-list">${recipe.instructions.map(step=>`<li>${esc(step)}</li>`).join('')}</ol>`:'<p class="no-ingredients">No steps saved yet.</p>'}${recipe.notes?`<h3>Notes</h3><p class="recipe-notes">${esc(recipe.notes)}</p>`:''}`;document.getElementById('editRecipe').dataset.recipeId=id;document.getElementById('recipeDetailsDialog').showModal()}
function renderRecipes(){
  const q=document.getElementById('search').value.toLowerCase(),grid=document.getElementById('recipeGrid'),filter=document.getElementById('recipeCategoryFilter');
  if(filter)activeRecipeCategory=filter.value;
  const recipes=state.recipes.filter(r=>(r.name.toLowerCase().includes(q)||(r.source||'').toLowerCase().includes(q))&&(activeRecipeCategory==='All categories'||recipeCategory(r)===activeRecipeCategory));
  grid.innerHTML=recipes.map(r=>{
    const cat=recipeCategory(r),link=recipeUrl(r.source),sourceLabel=link?new URL(link).hostname.replace(/^www\./,''):r.source||'My recipe';
    const badge=(!r.ingredients?.length||!r.instructions?.length)?'<span class="recipe-incomplete">Details to add</span>':'';
    return `<article class="card recipe"><div class="recipe-image"><button class="recipe-visual-open" data-open-recipe="${r.id}" aria-label="View ${esc(r.name)}">${r.emoji||'🍽️'}</button><div class="source-chip">${esc(sourceLabel)}</div></div><div class="recipe-body"><span class="recipe-category">${esc(cat)}</span>${badge}<h3><button class="recipe-title-open" data-open-recipe="${r.id}">${esc(r.name)}</button></h3><div class="recipe-meta"><span>◷ ${r.time||'Recipe'}</span><span>▤ ${r.ingredients?.length||0} ingredients</span></div>${r.notes?`<p style="color:var(--muted);font-size:11px;margin:10px 0 0">${esc(r.notes)}</p>`:''}<div class="recipe-actions"><button class="btn small" data-view-recipe="${r.id}">View recipe</button><button class="btn small" data-share-recipe="${r.id}">Share</button><button class="btn small" data-plan-recipe="${r.id}">＋ Plan it</button><button class="btn small" data-delete-recipe="${r.id}">Remove</button></div></div></article>`
  }).join('')+`<button class="add-tile" id="addTile"><span><b>＋ Save a recipe</b>From a link, a post, or your own notes</span></button>`;
  grid.querySelector('#addTile').onclick=()=>openRecipeEditor();
  grid.querySelectorAll('[data-open-recipe],[data-view-recipe]').forEach(b=>b.onclick=()=>showRecipeDetails(b.dataset.openRecipe||b.dataset.viewRecipe));
  grid.querySelectorAll('[data-plan-recipe]').forEach(b=>b.onclick=()=>openPlan(keyDate(monday(weekOffset)),'Dinner',b.dataset.planRecipe));
   grid.querySelectorAll('[data-delete-recipe]').forEach(b=>b.onclick=async()=>{try{await window.DinnerTableFirebase?.deleteRecipeShares?.(b.dataset.deleteRecipe)}catch(error){toast('The recipe could not be removed from the groups you shared it with. Try again.');return}state.recipes=state.recipes.filter(r=>r.id!==b.dataset.deleteRecipe);save()});
}
let editingRecipeId=null;document.getElementById('recipeCategoryFilter').onchange=renderRecipes;document.getElementById('closeRecipeDetails').onclick=()=>document.getElementById('recipeDetailsDialog').close();document.getElementById('newRecipe').onclick=()=>openRecipeEditor();function openRecipeEditor(recipe=null,isDraft=false){const form=document.getElementById('recipeForm');editingRecipeId=recipe?.id||null;form.reset();form.elements.name.value=recipe?.name||'';form.elements.source.value=recipe?.source||'';form.elements.category.value=recipeCategory(recipe||{});form.elements.ingredients.value=(recipe?.ingredients||[]).join('\n');form.elements.instructions.value=(recipe?.instructions||[]).join('\n');form.elements.notes.value=recipe?.notes||'';document.getElementById('recipeFormTitle').textContent=isDraft?'Review imported recipe':recipe?'Edit recipe':'Save a recipe';form.querySelector('button.primary').textContent=recipe?.id?'Save changes':'Save recipe';document.getElementById('recipeDialog').showModal()}document.getElementById('editRecipe').onclick=()=>{const recipe=state.recipes.find(item=>item.id===document.getElementById('editRecipe').dataset.recipeId);document.getElementById('recipeDetailsDialog').close();if(recipe)openRecipeEditor(recipe)};document.getElementById('recipeForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),recipe={id:editingRecipeId||crypto.randomUUID(),name:f.get('name').trim(),source:f.get('source').trim()||'My recipe',category:f.get('category'),ingredients:f.get('ingredients').split('\n').map(x=>x.trim()).filter(Boolean),instructions:f.get('instructions').split('\n').map(x=>x.trim()).filter(Boolean),notes:f.get('notes').trim(),emoji:state.recipes.find(item=>item.id===editingRecipeId)?.emoji||'🍽️',time:state.recipes.find(item=>item.id===editingRecipeId)?.time||''};if(!recipe.name)return;if(editingRecipeId){const index=state.recipes.findIndex(item=>item.id===editingRecipeId);if(index>=0)state.recipes[index]=recipe;toast('Recipe updated')}else{state.recipes.unshift(recipe);toast('Recipe saved to your box')}editingRecipeId=null;e.target.reset();document.getElementById('recipeDialog').close();save();persistRecipeToCloud(recipe);Promise.resolve(window.DinnerTableFirebase?.updateSharedRecipeSnapshot?.(recipe)).catch(()=>toast('Recipe saved, but its shared copy could not be updated.'))};

function recipeInstructions(raw){const out=[];const walk=value=>{if(typeof value==='string'){const line=value.trim();if(line)out.push(line);return}if(Array.isArray(value)){value.forEach(walk);return}if(value&&typeof value==='object'){if(value.name&&Array.isArray(value.itemListElement)){out.push(`${value.name}:`);walk(value.itemListElement);return}if(value.text)walk(value.text);else if(value.itemListElement)walk(value.itemListElement)}};walk(raw);return out}
function findRecipeSchema(root){let found=null;const seen=new Set();const visit=value=>{if(!value||found)return;if(Array.isArray(value)){value.forEach(visit);return}if(typeof value!=='object'||seen.has(value))return;seen.add(value);const type=value['@type'],types=Array.isArray(type)?type:[type];if(types.some(t=>String(t||'').split('/').pop()==='Recipe')){found=value;return}Object.values(value).forEach(visit)};visit(root);return found}
function importedCategory(raw){const value=Array.isArray(raw)?raw.join(' ').toLowerCase():String(raw||'').toLowerCase();if(/dessert|cake|cookie|pudding/.test(value))return'Dessert';if(/side|salad|vegetable/.test(value))return'Side';if(/snack|appetizer|starter/.test(value))return'Snack';if(/breakfast|brunch/.test(value))return'Breakfast';if(/drink|beverage|cocktail/.test(value))return'Drink';if(/main|entree|dinner/.test(value))return'Entree';return'Other'}
function recipeFromSchema(recipe,url){const ingredients=Array.isArray(recipe.recipeIngredient)?recipe.recipeIngredient.map(x=>String(x).trim()).filter(Boolean):[];const instructions=recipeInstructions(recipe.recipeInstructions);if(!ingredients.length&&!instructions.length)return null;return{id:crypto.randomUUID(),name:String(recipe.name||'Imported recipe').trim(),source:url,category:importedCategory(recipe.recipeCategory),ingredients,instructions,notes:String(recipe.description||'').trim(),emoji:'🍽️'}}
function markdownSection(lines,pattern){const start=lines.findIndex(line=>/^#{1,6}\s/.test(line)&&pattern.test(line.replace(/^#{1,6}\s*/,'')));if(start<0)return[];const level=(lines[start].match(/^#+/)||['##'])[0].length,out=[];for(let i=start+1;i<lines.length;i++){if(/^#{1,6}\s/.test(lines[i])){const sublevel=(lines[i].match(/^#+/)||[''])[0].length;if(sublevel<=level)break;continue}let line=lines[i].trim();if(!line)continue;line=line.replace(/^\s*(?:[-*+]\s+|\d+[.)]\s+)/,'').replace(/\s+#+$/,'').trim();if(line&&!/^source\s*:/i.test(line))out.push(line)}return out}
function parseReaderRecipe(content,title,url){const lines=String(content||'').split(/\r?\n/);let name=String(title||'').trim();if(!name){const heading=lines.find(line=>/^#\s+/.test(line));name=heading?heading.replace(/^#\s+/,'').trim():''}const ingredients=markdownSection(lines,/ingredient|what you(?:'|’)ll need|you will need/i);const instructions=markdownSection(lines,/direction|instruction|method|preparation|steps|how to make/i);if(!name||!ingredients.length&&!instructions.length)return null;return{id:crypto.randomUUID(),name,source:url,category:importedCategory(name),ingredients,instructions,notes:'',emoji:'🍽️'}}
async function importRecipeFromUrl(rawUrl){const pageUrl=new URL(rawUrl);if(!['http:','https:'].includes(pageUrl.protocol))throw new Error('Use a public http or https recipe link.');let directError='';try{const response=await fetch(pageUrl.href,{mode:'cors',credentials:'omit',redirect:'follow',headers:{Accept:'text/html,application/xhtml+xml'}});if(!response.ok)throw new Error(`The recipe site returned ${response.status}.`);const html=await response.text(),doc=new DOMParser().parseFromString(html,'text/html');for(const script of doc.querySelectorAll('script[type="application/ld+json"]')){try{const schema=findRecipeSchema(JSON.parse(script.textContent));if(schema){const recipe=recipeFromSchema(schema,pageUrl.href);if(recipe)return recipe}}catch{}}}catch(error){directError=error.message||'Direct access was blocked.'}
try{const response=await fetch(`https://r.jina.ai/${pageUrl.href}`,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error(`Reader returned ${response.status}.`);const body=await response.json(),data=body.data||body,recipe=parseReaderRecipe(data.content,data.title,pageUrl.href);if(recipe)return recipe;throw new Error('The page text did not contain clear ingredient and direction sections.')}catch(error){const detail=directError?` Direct import: ${directError}`:'';throw new Error(`Could not extract this recipe. Check that the page is public, or enter the recipe manually.${detail} Reader: ${error.message||'request failed'}`)}}function saveRecipeLinkOnly(url){const host=new URL(url).hostname.replace(/^www\./,'');const label=/tiktok/i.test(host)?'TikTok':/instagram/i.test(host)?'Instagram':host;const recipe={id:crypto.randomUUID(),name:`Saved from ${label}`,source:url,category:'Other',ingredients:[],instructions:[],notes:'',emoji:'🍽️',importIncomplete:true};state.recipes.unshift(recipe);document.getElementById('recipeImportDialog').close();document.getElementById('recipeImportForm').reset();document.getElementById('saveLinkOnly').hidden=false;save();persistRecipeToCloud(recipe);toast('Link saved to your recipe box. Add details whenever you’re ready.')}
document.getElementById('importRecipe').onclick=()=>{document.getElementById('importStatus').textContent='';document.getElementById('importStatus').className='import-status';document.getElementById('saveLinkOnly').hidden=false;document.getElementById('recipeImportDialog').showModal()};document.getElementById('saveLinkOnly').onclick=e=>{e.preventDefault();const url=new FormData(document.getElementById('recipeImportForm')).get('url').trim();if(url)saveRecipeLinkOnly(url)};document.getElementById('recipeImportForm').onsubmit=async e=>{if(e.submitter?.value==='cancel'){e.preventDefault();e.target.closest('dialog').close('cancel');return}if(e.submitter?.value==='save-link'){e.preventDefault();const url=new FormData(e.target).get('url').trim();if(url)saveRecipeLinkOnly(url);return}e.preventDefault();const f=new FormData(e.target),url=f.get('url').trim(),status=document.getElementById('importStatus'),submit=document.getElementById('importSubmit');status.textContent='Reading the page and looking for ingredients and directions…';status.className='import-status';submit.disabled=true;try{const recipe=state.recipeImporterUrl?await importRecipeViaWorker(url):await importRecipeFromUrl(url);state.recipes.unshift(recipe);document.getElementById('recipeImportDialog').close();e.target.reset();save();persistRecipeToCloud(recipe);toast('Recipe imported with ingredients and directions')}catch(error){status.textContent=error.message||'Could not import this recipe. You can still save its link and fill in the details later.';status.className='import-status error';document.getElementById('saveLinkOnly').hidden=false}finally{submit.disabled=false}};function showRecipeDetails(id){const recipe=state.recipes.find(r=>r.id===id);if(!recipe)return;const link=recipeUrl(recipe.source),content=document.getElementById('recipeDetailsContent');content.innerHTML=`<span class="recipe-category">${esc(recipeCategory(recipe))}</span><h2>${esc(recipe.name)}</h2><p class="details-source">${link?`<a href="${esc(link)}" target="_blank" rel="noopener noreferrer">Open original recipe ↗</a>`:`Source: ${esc(recipe.source||'My recipe')} · No link saved`}</p><h3>Ingredients</h3>${recipe.ingredients?.length?`<ul class="ingredient-list">${recipe.ingredients.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:'<p class="no-ingredients">No ingredients saved yet.</p>'}${recipe.instructions?.length?`<h3>Directions</h3><ol class="ingredient-list">${recipe.instructions.map(step=>`<li>${esc(step)}</li>`).join('')}</ol>`:'<p class="no-ingredients">No steps saved yet.</p>'}${recipe.notes?`<h3>Notes</h3><p class="recipe-notes">${esc(recipe.notes)}</p>`:''}`;document.getElementById('editRecipe').dataset.recipeId=id;document.getElementById('recipeDetailsDialog').showModal()}

state.recipeImporterUrl??='';
async function importRecipeViaWorker(url){const endpoint=new URL(state.recipeImporterUrl);if(!['http:','https:'].includes(endpoint.protocol))throw new Error('The recipe importer setting must be an http or https URL.');const response=await fetch(endpoint.href,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url})});let body={};try{body=await response.json()}catch{}if(!response.ok)throw new Error(body.error||`Recipe importer returned ${response.status}.`);if(!body.recipe||!body.recipe.name)throw new Error('The recipe importer returned incomplete recipe data.');const ingredients=Array.isArray(body.recipe.ingredients)?body.recipe.ingredients:[],instructions=Array.isArray(body.recipe.instructions)?body.recipe.instructions:[];if(!ingredients.length||!instructions.length)throw new Error(`The importer found the recipe name but not ${!ingredients.length&&!instructions.length?'the ingredients or steps':!ingredients.length?'the ingredients':'the steps'}. Try another public recipe page or enter those details manually.`);return{id:crypto.randomUUID(),name:String(body.recipe.name),source:String(body.recipe.source||url),category:String(body.recipe.category||'Other'),ingredients,instructions,notes:String(body.recipe.notes||''),emoji:'🍽️'}}
const PDF_JS_URL='https://cdn.jsdelivr.net/npm/pdfjs-dist@6.5.438/build/pdf.mjs';
const PDF_JS_WORKER_URL='https://cdn.jsdelivr.net/npm/pdfjs-dist@6.5.438/build/pdf.worker.mjs';
const TESSERACT_URL='https://cdn.jsdelivr.net/npm/tesseract.js@6.0.1/dist/tesseract.esm.min.js';
let ocrWorkerPromise=null;
async function getOcrWorker(){if(!ocrWorkerPromise)ocrWorkerPromise=import(TESSERACT_URL).then(module=>module.createWorker('eng')).catch(error=>{ocrWorkerPromise=null;throw error});return ocrWorkerPromise}
async function readImageText(image,status){status.textContent='Reading words from the picture on this device…';const worker=await getOcrWorker();const result=await worker.recognize(image);return result.data.text||''}
async function readPdfText(file,status){
  status.textContent='Opening the PDF…';
  const pdfjs=await import(PDF_JS_URL);
  pdfjs.GlobalWorkerOptions.workerSrc=PDF_JS_WORKER_URL;
  const pdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;
  const pageCount=Math.min(pdf.numPages,8),parts=[];
  if(pdf.numPages>pageCount)status.textContent=`This PDF has ${pdf.numPages} pages. I’ll read the first ${pageCount}.`;
  for(let pageNumber=1;pageNumber<=pageCount;pageNumber++){
    status.textContent=`Reading PDF page ${pageNumber} of ${pageCount}…`;
    const page=await pdf.getPage(pageNumber),content=await page.getTextContent(),pageLines=[];
    let line='';
    for(const item of content.items){
      if(typeof item.str!=='string')continue;
      line+=item.str;
      if(item.hasEOL){pageLines.push(line);line=''}else line+=' ';
    }
    if(line.trim())pageLines.push(line);
    const pageText=pageLines.join('\n');
    parts.push(pageText);
    if(pageText.replace(/\s/g,'').length<80){
      const viewport=page.getViewport({scale:1.5}),canvas=document.createElement('canvas');
      canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);
      await page.render({canvas,viewport}).promise;
      parts.push(await readImageText(canvas,status));
      canvas.width=canvas.height=0;
    }
  }
  return parts.join('\n');
}
function parseFileRecipe(text,fileName){const lines=String(text||'').replace(/\u0000/g,' ').replace(/[\t ]+/g,' ').split(/\r?\n/).map(line=>line.trim()).filter(Boolean);const isHeading=line=>/^(ingredients?|what you.?ll need|you will need|directions?|instructions?|method|preparation|steps?|notes?|nutrition|nutrition facts|recipe)$/i.test(line.replace(/[:：]+$/,''));const ingredientAt=lines.findIndex(line=>/^ingredients?\b/i.test(line)),stepAt=lines.findIndex(line=>/^(directions?|instructions?|method|preparation|steps?)\b/i.test(line));let ingredients=[],instructions=[];if(ingredientAt>=0){const end=lines.findIndex((line,index)=>index>ingredientAt&&(/^(directions?|instructions?|method|preparation|steps?|notes?|nutrition)\b/i.test(line)));ingredients=lines.slice(ingredientAt+1,end<0?lines.length:end).filter(line=>!isHeading(line))}if(stepAt>=0){const end=lines.findIndex((line,index)=>index>stepAt&&/^(notes?|nutrition|ingredients?)\b/i.test(line));instructions=lines.slice(stepAt+1,end<0?lines.length:end).filter(line=>!isHeading(line))}if(!ingredients.length)ingredients=lines.filter(line=>/^(?:[-•*]\s*)?(?:\d+(?:[./]\d+)?\s*(?:cups?|tbsp|tsp|tablespoons?|teaspoons?|oz|ounces?|lb|pounds?|g|kg|ml|l|cloves?|cans?|packages?|slices?|pinches?|pieces?)\b|to taste\b)/i.test(line));if(!instructions.length)instructions=lines.filter(line=>/^\s*(?:\d+[.)]|step\s+\d+|•)\s*/i.test(line)).map(line=>line.replace(/^\s*(?:\d+[.)]|step\s+\d+|•)\s*/i,''));let name=lines.find(line=>!isHeading(line)&&!/^\s*(?:[-•*]|\d+[.)]|step\s+\d+)/i.test(line)&&!/^ingredients?\b/i.test(line))||'';name=name.replace(/\s+/g,' ').slice(0,120);if(!name)name=String(fileName||'Imported recipe').replace(/\.[^.]+$/,'').replace(/[_-]+/g,' ').trim()||'Imported recipe';return{id:crypto.randomUUID(),name,source:`Imported from ${fileName}`,category:importedCategory(name),ingredients,instructions,notes:(!ingredients.length||!instructions.length)?lines.join('\n').slice(0,3000):'',emoji:'🍽️'}}
document.getElementById('importRecipeFile').onclick=()=>{document.getElementById('fileImportStatus').textContent='';document.getElementById('fileImportStatus').className='import-status';document.getElementById('recipeFileDialog').showModal()};document.getElementById('recipeFileForm').onsubmit=async e=>{if(e.submitter?.value==='cancel')return;e.preventDefault();const file=new FormData(e.target).get('file'),status=document.getElementById('fileImportStatus'),submit=document.getElementById('fileImportSubmit');if(!file)return;if(file.size>15*1024*1024){status.textContent='Please choose a file smaller than 15 MB.';status.className='import-status error';return}submit.disabled=true;status.className='import-status';try{const isPdf=file.type==='application/pdf'||file.name.toLowerCase().endsWith('.pdf'),text=isPdf?await readPdfText(file,status):await readImageText(file,status);if(!text.trim())throw new Error('No readable text was found. Try a clearer picture or enter the recipe manually.');const draft=parseFileRecipe(text,file.name);document.getElementById('recipeFileDialog').close();e.target.reset();openRecipeEditor(draft,true);toast('Review the extracted recipe, make any corrections, then save it.')}catch(error){status.textContent=error.message||'Could not read that file. You can still create the recipe manually.';status.className='import-status error'}finally{submit.disabled=false}};
function renderImporterSettings(){const panel=document.getElementById('recipeImportSettings');if(!panel)return;panel.innerHTML=`<div class="card importer-settings"><div class="eyebrow">Server-side link fetching</div><h3>Recipe import service</h3><p>To import pages that block browser access, deploy the free Cloudflare Worker in the project’s <code>worker</code> folder, then paste its URL here. Keep the URL as a full https:// address.</p><form id="importerEndpointForm" class="importer-endpoint-form"><input name="endpoint" type="url" value="${esc(state.recipeImporterUrl||'')}" placeholder="https://your-worker.workers.dev" aria-label="Recipe importer Worker URL"><button class="btn primary" type="submit">Save importer URL</button></form><div class="importer-configured">${state.recipeImporterUrl?(window.DinnerTableFirebase?.signedIn?'Importer URL saved to your Firebase account.':'Importer URL saved in this browser.'):'No server-side importer configured yet; direct browser import may be blocked by recipe sites.'}</div></div>`;panel.querySelector('#importerEndpointForm').onsubmit=e=>{e.preventDefault();state.recipeImporterUrl=new FormData(e.target).get('endpoint').trim();save();toast(state.recipeImporterUrl?'Recipe importer connected':'Recipe importer URL cleared')}}
